import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthPage, ProfilePage, ManagerDashboardNew, ProtectedRoute, EnhancedBillUpload } from "./components";
import "./styles.css";

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={<AuthPage />} />
          <Route path="/register" element={<AuthPage />} />

          {/* Protected Routes */}
          <Route 
            path="/profile" 
            element={
              <ProtectedRoute>
                <ProfilePage />
              </ProtectedRoute>
            } 
          />
          {/* Primary Bill Upload Route - Enhanced Processing */}
          <Route 
            path="/upload" 
            element={
              <ProtectedRoute>
                <EnhancedBillUpload />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/enhanced-upload" 
            element={
              <ProtectedRoute>
                <EnhancedBillUpload />
              </ProtectedRoute>
            } 
          />

          {/* Manager Dashboard */}
          <Route 
            path="/team-bills" 
            element={
              <ProtectedRoute>
                <ManagerDashboardNew />
              </ProtectedRoute>
            } 
          />

          {/* Default redirect */}
          <Route path="/" element={<Navigate to="/login" replace />} />
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
